import sys

def main():
    import sys
    import sys
    from collections import defaultdict, deque

    def read_input():
        import sys
        input = sys.stdin.read().split()
        n = int(input[0])
        m = int(input[1])
        edges = []
        idx = 2
        for _ in range(m):
            u = int(input[idx]) - 1
            v = int(input[idx + 1]) - 1
            c = input[idx + 2]
            edges.append((u, v, c))
            idx += 3
        return n, m, edges

    def solve(n, m, edges):
        adj = defaultdict(list)
        color = [0] * n
        for u, v, c in edges:
            adj[u].append(v)
            adj[v].append(u)
            if c == 'R':
                color[u] ^= 1
                color[v] ^= 1

        visited = [False] * n
        groups = [None] * n
        group_id = 0

        def bfs(start):
            nonlocal group_id
            queue = deque([start])
            visited[start] = True
            groups[start] = group_id
            while queue:
                node = queue.popleft()
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        groups[neighbor] = group_id
                        queue.append(neighbor)

        for i in range(n):
            if not visited[i]:
                bfs(i)
                group_id += 1

        group_counts = [0] * group_id
        for c, g in zip(color, groups):
            group_counts[g] += c

        odd_groups = [g for g, count in enumerate(group_counts) if count % 2 != 0]

        if len(odd_groups) > 2:
            return -1
        elif len(odd_groups) == 0:
            return 0, []
        elif len(odd_groups) == 1:
            for u in range(n):
                if groups[u] == odd_groups[0]:
                    return 1, [u + 1]
        else:
            g1, g2 = odd_groups
            for u in range(n):
                if groups[u] == g1:
                    for v in range(n):
                        if groups[v] == g2:
                            return 2, [u + 1, v + 1]

    n, m, edges = read_input()
    result = solve(n, m, edges)
    if result == -1:
        print(-1)
    else:
        k, moves = result
        print(k)
        print(*moves)

if __name__ == "__main__":
    main()
